#!/usr/bin/env python3
"""Auto-generated eval script for the Software Factory.

This script was generated by `factory discover`. It runs each eval dimension
as a subprocess and outputs JSON to stdout.

Output format:
    {"results": [{"name": str, "score": float, "weight": float, "passed": bool, "details": str}, ...]}

You can edit this file to add custom evals or adjust weights.
Once edited, it becomes a Tier 1 (explicit) eval — the factory will use it as-is.
"""

import json
import subprocess
import sys

def eval_tests() -> dict:
    """Run test suite: npm test"""
    try:
        result = subprocess.run(
            ['npm', 'test'],
            capture_output=True,
            text=True,
            timeout=120,
        )
        passed = result.returncode == 0
        if passed:
            score = 1.0
        else:
            # Partial score: count output lines as a rough error metric
            error_lines = [ln for ln in (result.stdout + result.stderr).splitlines() if ln.strip()]
            if not error_lines:
                score = 0.0
            else:
                score = max(0.0, 1.0 - len(error_lines) * 0.05)
        return {
            "name": 'tests',
            "score": score,
            "weight": 0.8333333333333334,
            "passed": passed,
            "details": (result.stdout or result.stderr).strip()[-500:],
        }
    except subprocess.TimeoutExpired:
        return {
            "name": 'tests',
            "score": 0.0,
            "weight": 0.8333333333333334,
            "passed": False,
            "details": "Timed out after 120s",
        }

def eval_observability() -> dict:
    """Analyze observability coverage: logging, structured logging, request tracing."""
    import re
    from pathlib import Path

    skip = {
        "tests", "test", ".venv", "venv", "node_modules", "__pycache__",
        ".git", ".factory", "eval", "dist", "build", ".mypy_cache",
    }
    fn_pats = [
        r"\bfunction\s+\w+",
        r"\basync\s+function\s+\w+",
        r"\bexport\s+function\s+\w+",
        r"\bexport\s+async\s+function\s+\w+",
        r"\bexport\s+const\s+\w+\s*=",
        r"\bconst\s+\w+\s*=\s*(?:async\s*)?\([^)]*\)\s*=>",
        r"\bconst\s+\w+\s*=\s*(?:async\s*)?\w+\s*=>",
    ]
    log_pats = [
        r"\bconsole\.log\(",
        r"\bconsole\.warn\(",
        r"\bconsole\.error\(",
        r"\bconsole\.info\(",
        r"\blogger\.\w+\(",
        r"\blog\.\w+\(",
    ]
    struct_pats = [r"\bpino\b", r"\bwinston\b", r"\bbunyan\b", r"\bstructlog\b"]
    trace_pats = [r"\bopentelemetry\b", r"\btrace\b", r"\bspan\b",
                  r"\bTraceContext\b"]

    sources = []
    for ext in ("*.ts", "*.tsx"):
        sources.extend(f for f in Path(".").rglob(ext)
                       if not any(p in f.parts for p in skip))
    total_fn = logged_fn = total_log = 0
    has_struct = has_trace = False

    for src in sources:
        try:
            code = src.read_text(errors="replace")
        except OSError:
            continue
        for pat in fn_pats:
            total_fn += len(re.findall(pat, code))
        for pat in log_pats:
            hits = len(re.findall(pat, code))
            total_log += hits
        fn_blocks = list(re.finditer(
            r"(?:export\s+)?(?:async\s+)?function\s+\w+[^{]*\{", code))
        arrow_blocks = list(re.finditer(
            r"(?:export\s+)?const\s+\w+\s*=\s*(?:async\s*)?\(?[^)]*\)?\s*=>\s*\{", code))
        for match in fn_blocks + arrow_blocks:
            start = match.start()
            depth = 0
            end = start
            for i in range(match.end() - 1, len(code)):
                if code[i] == '{':
                    depth += 1
                elif code[i] == '}':
                    depth -= 1
                    if depth == 0:
                        end = i + 1
                        break
            body = code[start:end]
            for pat in log_pats:
                if re.search(pat, body):
                    logged_fn += 1
                    break
        for pat in struct_pats:
            if re.search(pat, code):
                has_struct = True
        for pat in trace_pats:
            if re.search(pat, code, re.IGNORECASE):
                has_trace = True

    if total_fn == 0:
        return {"name": "observability", "score": 0.0, "weight": 0.16666666666666669,
                "passed": True, "details": "No functions found to analyze"}

    cov = min(1.0, logged_fn / total_fn)
    density = min(1.0, total_log / max(total_fn, 1))
    score = 0.40 * cov + 0.25 * float(has_struct) + 0.20 * float(has_trace) + 0.15 * density

    details = (f"coverage={cov:.0%} ({logged_fn}/{total_fn}), "
               f"structured={'yes' if has_struct else 'no'}, "
               f"tracing={'yes' if has_trace else 'no'}, "
               f"density={density:.0%}")

    return {"name": "observability", "score": round(score, 3), "weight": 0.16666666666666669,
            "passed": score >= 0.3, "details": details}

# Register all eval functions here.
EVALS = [eval_tests, eval_observability]


def main() -> None:
    results = [fn() for fn in EVALS]
    output = {"results": results}
    json.dump(output, sys.stdout, indent=2)
    print()  # trailing newline


if __name__ == "__main__":
    main()
